// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { Triangle } from "@remotion/shapes";

// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map(
        (font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`
      )
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type ScrollingWordListProps = Record<string, any>;

const ScrollingWordList: React.FC<ScrollingWordListProps> = ({
  backgroundColor = "#f4f4f4",
  transparentBackground = false,
  durationInSeconds = 5,
  wordList = "Driven, Vision, Momentum, Focus, Strength, Forge, Pursuit, Flow",
  startWord = "Focus",
  endWord = "Pursuit",
  logoImage = "https://malloy.blob.core.windows.net/web/testing/ChatGPT-Logo.png",
  primaryTextColor = "#1a1a1a",
  highlightColor = "#ff6b6b",
  fontSize = 80,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgStyle = transparentBackground ? "transparent" : backgroundColor;

  // --- Layout Constants ---
  const LOGO_SECTION_WIDTH = width * 0.45;
  const LIST_SECTION_X = width * 0.55;
  const ROW_HEIGHT = fontSize * 1.5;

  // --- Data Parsing & Preparation ---
  // Parse the textarea string into an array, handling commas and newlines
  const parsedWordList = React.useMemo(() => {
    return wordList
      .split(/[\n,]+/) // Split by newline or comma
      .map((w) => w.trim())
      .filter((w) => w.length > 0);
  }, [wordList]);

  // Ensure valid start/end words, fallback to defaults if not found
  const safeStart = parsedWordList.includes(startWord)
    ? startWord
    : parsedWordList[0];
  const safeEnd = parsedWordList.includes(endWord)
    ? endWord
    : parsedWordList[parsedWordList.length - 1];

  // Construct a deterministic linear path: Start -> ... -> End
  const displayList = React.useMemo(() => {
    const listLength = parsedWordList.length;
    
    // Safety break for empty lists
    if (listLength === 0) return [];

    // Find first occurrence of start
    const startIndex = parsedWordList.indexOf(safeStart);

    let path: string[] = [];
    let currentIndex = startIndex;

    // Push words until we hit the end word
    let foundEnd = false;
    let iterations = 0;

    // Limit iterations to prevent infinite loops on malformed data
    while (!foundEnd && iterations < listLength * 2) {
      const word = parsedWordList[currentIndex % listLength];
      path.push(word);

      if (word === safeEnd && iterations > 0) {
        foundEnd = true;
      }

      currentIndex++;
      iterations++;
    }

    // Add padding for visual continuity (scrolling into view)
    const paddingCount = 6;
    const prefix = Array.from({ length: paddingCount }).map((_, i) => {
      const idx =
        (startIndex - paddingCount + i + listLength * 10) % listLength;
      return parsedWordList[idx];
    });

    const suffix = Array.from({ length: paddingCount }).map((_, i) => {
      const idx = (currentIndex + i) % listLength;
      return parsedWordList[idx];
    });

    return [...prefix, ...path, ...suffix];
  }, [parsedWordList, safeStart, safeEnd]);

  const paddingCount = 6;
  const activeStartIndex = paddingCount;
  const activeEndIndex = displayList.length - paddingCount - 1;

  // --- Animation Logic ---
  const centerY = height / 2;

  const getContainerY = (targetIndex: number) => {
    return centerY - targetIndex * ROW_HEIGHT - ROW_HEIGHT / 2;
  };

  const startY = getContainerY(activeStartIndex);
  const endY = getContainerY(activeEndIndex);

  // Smooth easing for start and stop
  const progress = interpolate(frame, [0, durationInFrames], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const currentContainerY = interpolate(progress, [0, 1], [startY, endY]);

  // Logo Animation (Subtle fade/slide in)
  const logoOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const logoOffset = interpolate(frame, [0, 20], [20, 0], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyle }}>
      {/* --- Left Section: Logo --- */}
      <AbsoluteFill
        style={{
          width: LOGO_SECTION_WIDTH,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-end", // Align close to the center divider
          justifyContent: "center",
          paddingRight: 60,
          opacity: logoOpacity,
          transform: `translateX(${logoOffset}px)`,
        }}
      >
        <div style={{ position: "relative", width: "100%", display: "flex", justifyContent: "flex-end" }}>
          {logoImage ? (
            <img
              src={logoImage}
              alt="Logo"
              style={{
                maxWidth: "100%",
                maxHeight: fontSize * 4,
                objectFit: "contain",
              }}
            />
          ) : null}
        </div>
      </AbsoluteFill>

      {/* --- Center Divider: Arrow --- */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          pointerEvents: "none",
        }}
      >
        {/* We position the arrow exactly between the two visual columns */}
        <div style={{ transform: `translateX(${width * 0.02}px)` }}>
          <Triangle
            length={40}
            direction="right"
            fill={primaryTextColor}
            style={{ opacity: 0.8 }}
          />
        </div>
      </AbsoluteFill>

      {/* --- Right Section: Scrolling List --- */}
      <AbsoluteFill
        style={{
          left: LIST_SECTION_X,
          width: width - LIST_SECTION_X,
          overflow: "hidden", // Mask the list
        }}
      >
        {/* The moving container */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            transform: `translateY(${currentContainerY}px)`,
            display: "flex",
            flexDirection: "column",
          }}
        >
          {displayList.map((word, i) => {
            const itemCenterY =
              currentContainerY + i * ROW_HEIGHT + ROW_HEIGHT / 2;
            const distFromCenter = Math.abs(itemCenterY - centerY);

            const isActive = distFromCenter < ROW_HEIGHT / 2;

            const itemColor = isActive ? highlightColor : primaryTextColor;
            const itemOpacity = interpolate(
              distFromCenter,
              [0, height * 0.4],
              [1, 0.2],
              { extrapolateRight: "clamp" }
            );
            const itemScale = interpolate(
              distFromCenter,
              [0, height * 0.4],
              [1, 0.9],
              { extrapolateRight: "clamp" }
            );

            return (
              <div
                key={`${word}-${i}`}
                style={{
                  height: ROW_HEIGHT,
                  display: "flex",
                  alignItems: "center",
                  paddingLeft: 40, // Space from the arrow
                  fontFamily: "Inter",
                  fontWeight: 700,
                  fontSize: fontSize,
                  color: itemColor,
                  opacity: itemOpacity,
                  transform: `scale(${itemScale})`,
                  transformOrigin: "left center",
                }}
              >
                {word}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* Optional: Vignette or Gradient Masks to soften edges of the list */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(to bottom, ${bgStyle} 0%, transparent 20%, transparent 80%, ${bgStyle} 100%)`,
          pointerEvents: "none",
          left: LIST_SECTION_X,
          width: width - LIST_SECTION_X,
        }}
      />
    </AbsoluteFill>
  );
};

export default ScrollingWordList;